request:
{
 "project": "OUTBREAK MANAGEMENT FUNCTIONAL REQUIREMENTS",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [
  {
   "speaker": "Analyst",
   "act": "echo",
   "content": [
    "Systems supporting OM must have the capability to capture data about organizations (e.g., a local health department, a university, a professional association) involved in an OM investigation, including: organization name, location, and contact information."
   ]
  },
  {
   "speaker": "Client",
   "act": "confirm"
  },
  {
   "speaker": "EndUser",
   "act": "state",
   "content": [
    "Systems supporting OM must have the capability to capture data about any animals involved in an OM investigation, including: type (dog, monkey, etc), age, gender, owner's name and address, color, weight, and species."
   ]
  }
 ],
 "turns": [
  {
   "id": "M1:T21",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must have the capability to capture data for any object involved in an OM investigation, such as a letter, invoice, food item, or any object that cannot be classified as a \"person, organization, place, or animal.\" Collected data may include: name of the object, type, physical descriptors, address, identification number (e.g. serial number, package slip number), and relevant dates and times (e.g., invoice date, shipping date, packaging date).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T22",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must have the capability to capture data about any public or private gathering of people (e.g., church social, ball game) involved in an OM investigation, including: time, location, nature of the event, etc.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T23",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T24",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'health event data' and asks about it."
  },
  {
   "id": "M1:T25",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "When a health event is investigated, it must be assigned an event identifier (i.e., Event ID) that is unique within the jurisdiction.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T26",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Data describing the health event should be captured, including the reason for the investigation, the category of event (e.g. environmental, infectious), the date the event began, the suspected agent (if known) or investigation focus, the geographic area impacted by the event, as well as the event status (e.g., open, closed).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T27",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'health event data'."
  },
  {
   "id": "M1:T28",
   "speaker": "EndUser",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T29",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'travel history and conveyance data' and asks about it."
  },
  {
   "id": "M1:T30",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Information about each leg of a trip, as well as the parent information about the trip, should be captured.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T31",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "For example, if a person who lives in Georgia travels to Seattle and becomes exposed to monkey pox, then visits a friend in Santa Fe, travel history and conveyance data should be noted accordingly for each place the exposed person traveled.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T32",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Travel history data to be collected for an animal or object should include shipping invoices, animal shelter delivery and adoption receipts, and delivery schedules (including delivery vehicle and driver information).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T33",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T34",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'case investigation and exposure contact data' and asks about it."
  },
  {
   "id": "M1:T35",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Because attributes of both case and exposure data may describe the same entity, systems supporting OM must have the ability to avoid capturing redundant entity demographic information.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T36",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Case data about the entity should include: a case identifier (i.e., Case ID) that is unique within the jurisdiction being reported, the suspected agent, case diagnosis, health status (e.g., no symptoms, acute illness), case status (e.g., confirmed, probable, suspect), investigation dates, clinical history, symptom onset date and time, epidemiological links to other cases, and priority (e.g., high, medium, low).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T37",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T38",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Epidemiological (epi) data must be collected to assist in the case investigation of events.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T39",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T40",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Detailed data must be collected about the source of exposure as well as the exposed entity to support contact exposure tracing.",
     "role": "statement"
    },
    {
     "text": "Epi data must be collected to assist in the exposure investigation of health events.",
     "role": "statement"
    }
   ]
  }
 ]
}
